{
  "command": "echo "=== 现在工作树是 HEAD 完全相同 ==="
git diff --stat
echo ""
echo "=== 看 unity 8 篇当前的 **Symbol** 残留(应该 0) ==="
python3 -c "
import re, glob
for f in sorted(glob.glob('OneNote/unity/脚本开发/*.md')):
    c = open(f, encoding='utf-8').read()
    lines = c.split('\n')
    in_cs = False
    remaining = 0
    for line in lines:
        if re.match(r'^\`\`\`', line):
            if re.match(r'^\`\`\`(cs|csharp|c#)\\s*\$', line, re.IGNORECASE):
                in_cs = True
            else:
                in_cs = False
            continue
        if in_cs:
            remaining += len(re.findall(r'\*\*[A-Za-z_]\w*\*\*', line))
    if remaining:
        print(f'{f}: {remaining}')
print('all clear')
"
echo ""
echo "=== 现在我 commit 包含 unity 文件吗 ==="
git show HEAD --stat | grep unity"
}

